using Fylkren.Api.Risks;
using Microsoft.EntityFrameworkCore;
namespace Fylkren.Api.Persistence;

internal static class RiskModelConfiguration
{
    internal static void ConfigureRisks(this ModelBuilder m)
    {
        var r = m.Entity<Risk>(); r.ToTable("risks"); r.HasKey(x => x.Id); r.Property(x => x.Id).HasColumnName("id"); r.Property(x => x.SiteId).HasColumnName("site_id"); r.Property(x => x.ObjectType).HasColumnName("object_type").HasMaxLength(30); r.Property(x => x.ObjectId).HasColumnName("object_id"); r.Property(x => x.CreatedByPersonId).HasColumnName("created_by_person_id"); r.Property(x => x.CreatedAt).HasColumnName("created_at"); r.HasIndex(x => new { x.SiteId, x.ObjectType, x.ObjectId });
        var v = m.Entity<RiskRevision>(); v.ToTable("risk_revisions"); v.HasKey(x => x.Id); v.Property(x => x.Id).HasColumnName("id"); v.Property(x => x.RiskId).HasColumnName("risk_id"); v.Property(x => x.Version).HasColumnName("version"); v.Property(x => x.Title).HasColumnName("title").HasMaxLength(200); v.Property(x => x.Description).HasColumnName("description").HasMaxLength(10000); v.Property(x => x.Probability).HasColumnName("probability"); v.Property(x => x.Impact).HasColumnName("impact"); v.Property(x => x.Score).HasColumnName("score"); v.Property(x => x.Level).HasColumnName("level").HasMaxLength(30); v.Property(x => x.OwnerPersonId).HasColumnName("owner_person_id"); v.Property(x => x.OwnerNameSnapshot).HasColumnName("owner_name_snapshot").HasMaxLength(200); v.Property(x => x.Status).HasColumnName("status").HasMaxLength(30); v.Property(x => x.DueDate).HasColumnName("due_date"); v.Property(x => x.ResidualProbability).HasColumnName("residual_probability"); v.Property(x => x.ResidualImpact).HasColumnName("residual_impact"); v.Property(x => x.ResidualScore).HasColumnName("residual_score"); v.Property(x => x.ResidualLevel).HasColumnName("residual_level").HasMaxLength(30); v.Property(x => x.RecordedByPersonId).HasColumnName("recorded_by_person_id"); v.Property(x => x.RecordedAt).HasColumnName("recorded_at"); v.HasOne<Risk>().WithMany(x => x.Revisions).HasForeignKey(x => x.RiskId).OnDelete(DeleteBehavior.Restrict); v.HasIndex(x => new { x.RiskId, x.Version }).IsUnique();
        var a = m.Entity<RiskMitigation>(); a.ToTable("risk_mitigations"); a.HasKey(x => x.Id); a.Property(x => x.Id).HasColumnName("id"); a.Property(x => x.RiskId).HasColumnName("risk_id"); a.Property(x => x.CreatedByPersonId).HasColumnName("created_by_person_id"); a.Property(x => x.CreatedAt).HasColumnName("created_at"); a.HasOne(x => x.Risk).WithMany(x => x.Mitigations).HasForeignKey(x => x.RiskId).OnDelete(DeleteBehavior.Restrict);
        var ar = m.Entity<RiskMitigationRevision>(); ar.ToTable("risk_mitigation_revisions"); ar.HasKey(x => x.Id); ar.Property(x => x.Id).HasColumnName("id"); ar.Property(x => x.MitigationId).HasColumnName("mitigation_id"); ar.Property(x => x.Version).HasColumnName("version"); ar.Property(x => x.Action).HasColumnName("action").HasMaxLength(4000); ar.Property(x => x.OwnerPersonId).HasColumnName("owner_person_id"); ar.Property(x => x.OwnerNameSnapshot).HasColumnName("owner_name_snapshot").HasMaxLength(200); ar.Property(x => x.Status).HasColumnName("status").HasMaxLength(30); ar.Property(x => x.DueDate).HasColumnName("due_date"); ar.Property(x => x.RecordedByPersonId).HasColumnName("recorded_by_person_id"); ar.Property(x => x.RecordedAt).HasColumnName("recorded_at"); ar.HasOne<RiskMitigation>().WithMany(x => x.Revisions).HasForeignKey(x => x.MitigationId).OnDelete(DeleteBehavior.Restrict); ar.HasIndex(x => new { x.MitigationId, x.Version }).IsUnique();
    }
}
